INSERT INTO items VALUES('workshop.plurals.repair.4',2,'interactive.workshops',2,'morphology.noun.plural','sentence-editing','repair','{"category":"grammar","title":"复数词尾小工厂","gradeMin":1,"id":"workshop.plurals.repair.4","type":"repair","context":"目标意思：外面有两辆公交车。 找到一处需要调整的词块，只改这一处。","prompt":"点选一个词块，填写符合情境的新词或短语。","editing":{"parts":[{"id":"p0","text":"Two"},{"id":"p1","text":"bus"},{"id":"p2","text":"are"},{"id":"p3","text":"outside"},{"id":"p4","text":"."}]}}','{"answers":["[\"p1\",\"buses\"]","[\"p1\",\"busses\"]"],"repairs":[{"partId":"p1","replacements":["buses","busses"]}],"solutionSentences":["Two buses are outside.","Two busses are outside."],"evidenceTargets":["workshop-target:morphology.noun.plural:c04e027e4990a"],"explanation":"Two buses are outside. 外面有两辆公交车。 这里按常见复数规则分拣：加s、加es、辅音字母加y变ies，或记住不规则形式。toy和day里的y前是元音字母，直接加s。 bus的常用复数是buses，也接受美式变体busses。","hint":"这里按常见复数规则分拣：加s、加es、辅音字母加y变ies，或记住不规则形式。toy和day里的y前是元音字母，直接加s。","family":"workshop-sentence-aa98a110a7e39b19","workshopId":"plurals"}','published');
